type Channel = { id:string; community_id:string; name:string; type:'text'|'screen'; position:number };
type Community = { id:string; name:string; owner_id:string; icon:string; icon_color:string; icon_image:string|null; invite_code:string; role:'owner'|'admin'|'member'; channels:Channel[] };
type Message = { id:string; channel_id:string; author_id:string; username:string; display_name:string; avatar_icon:string; avatar_color:string; avatar_image:string|null; content:string; created_at:string; edited_at?:string|null };
type Member = { id:string; username:string; display_name:string; avatar_icon:string; avatar_color:string; avatar_image:string|null; last_seen:string; role:string; online?:boolean };
type IconOption = { id:string; label:string; Icon:LucideIcon };
type AudioShareMode = 'window'|'system'|'none';
type CaptureInfo = { surface:'browser'|'window'|'monitor'|'unknown'; hasAudio:boolean; mode:AudioShareMode };
type StreamQuality = 'economy'|'balanced'|'game';
type QualityProfile = { label:string; description:string; width:number; height:number; fps:number; maxBitrate:number; contentHint:'detail'|'motion'; degradationPreference:RTCDegradationPreference; layers:VideoPreset[] };
type CameraQuality = 'economy'|'balanced'|'high';
type CameraFit = 'cover'|'contain';
type ViewerZoom = {scale:number;x:number;y:number};
type ScreenSelection = {video:boolean;audio:boolean};
type ScreenSource = {id:string;label:string;isLocal:boolean;videoPublication:any;audioPublication?:any;videoTrack?:RemoteTrack|LocalTrack;audioTrack?:RemoteTrack;meta?:CaptureInfo|null};
type CameraSource = {id:string;label:string;isLocal:boolean;publication:any;track?:RemoteTrack|LocalTrack;mirror:boolean;fit:CameraFit};
function defaultScreenSelection(source:ScreenSource,index:number,limit:number):ScreenSelection{return{video:source.isLocal||limit===0||index<limit,audio:!source.isLocal&&Boolean(source.audioPublication)};}
const DEFAULT_VIEWER_ZOOM:ViewerZoom={scale:1,x:0,y:0};
const ZOOM_STEPS=[0.5,0.75,1,1.25,1.5,2,2.5,3];
function clampZoom(value:number){return Math.min(3,Math.max(0.5,value));}
function nextZoom(value:number,direction:1|-1){const current=ZOOM_STEPS.reduce((closest,step)=>Math.abs(step-value)<Math.abs(closest-value)?step:closest,1);const index=ZOOM_STEPS.indexOf(current);return ZOOM_STEPS[Math.min(ZOOM_STEPS.length-1,Math.max(0,index+direction))];}
type CameraPreferences = { deviceId:string; quality:CameraQuality; mirror:boolean; fit:CameraFit };
type CameraQualityProfile = { label:string; description:string; width:number; height:number; fps:number; maxBitrate:number; layers:VideoPreset[] };
