function loadCameraPreferences():CameraPreferences{try{const saved=JSON.parse(localStorage.getItem('telahub-camera-preferences')||'{}');return{deviceId:typeof saved.deviceId==='string'?saved.deviceId:'',quality:saved.quality in CAMERA_QUALITY_PROFILES?saved.quality:'balanced',mirror:typeof saved.mirror==='boolean'?saved.mirror:true,fit:saved.fit==='contain'?'contain':'cover'};}catch{return{deviceId:'',quality:'balanced',mirror:true,fit:'cover'};}}

const ICON_OPTIONS:IconOption[]=[{id:'user',label:'Pessoa',Icon:UserRound},{id:'users',label:'Equipe',Icon:Users},{id:'sparkles',label:'Brilho',Icon:Sparkles},{id:'gamepad',label:'Jogo',Icon:Gamepad2},{id:'code',label:'Código',Icon:Code2},{id:'rocket',label:'Foguete',Icon:Rocket},{id:'crown',label:'Coroa',Icon:Crown},{id:'shield',label:'Escudo',Icon:ShieldCheck},{id:'palette',label:'Arte',Icon:Palette},{id:'music',label:'Música',Icon:Music2},{id:'coffee',label:'Café',Icon:Coffee},{id:'cat',label:'Gato',Icon:Cat},{id:'star',label:'Estrela',Icon:Star}];
