  async function stopCamera(){if(!room)return;const publication=room.localParticipant.getTrackPublication(Track.Source.Camera);if(publication?.track)await room.localParticipant.unpublishTrack(publication.track,true);setCameraOn(false);socket.emit('camera:status',{channelId:channel.id,active:false});socket.emit('media:release',{channelId:channel.id,kind:'camera'});setVersion(value=>value+1);}
