  function selectAvailableScreens(){setScreenSelections(previous=>{const next:{[key:string]:ScreenSelection}={...previous};let active=0;screenSources.forEach((source,index)=>{const current=selectionFor(source,index,previous);const video=source.isLocal||screenVideoLimit===0||active<screenVideoLimit;if(video)active+=1;next[source.id]={...current,video};});return next;});}
  function clearScreenVideos(){setScreenSelections(previous=>Object.fromEntries(screenSources.map((source,index)=>[source.id,{...selectionFor(source,index,previous),video:false,audio:false}])));}
