    {screenAudioTracks.length>0&&<section className="audio-only-panel" aria-label="Controles de áudio das transmissões"><div className="share-preferences-title"><Volume2 size={16}/><div><strong>Áudio ativo sem vídeo</strong><span>O áudio continua tocando mesmo quando o vídeo está desativado.</span></div></div>{screenAudioTracks.map(item=><AudioOutput key={item.id} track={item.track} label={item.label} controllable/>)}</section>}
