function Chat({channel,user,socket}:{channel:Channel;user:User;socket:Socket}){
  const [messages,setMessages]=useState<Message[]>([]); const [content,setContent]=useState(''); const [typing,setTyping]=useState<string[]>([]); const [loading,setLoading]=useState(true); const [loadError,setLoadError]=useState(''); const [sendError,setSendError]=useState(''); const [pending,setPending]=useState(false); const [newMessages,setNewMessages]=useState(0); const endRef=useRef<HTMLDivElement>(null); const messagesRef=useRef<HTMLDivElement>(null); const typingTimer=useRef<number|undefined>(undefined); const nearBottomRef=useRef(true);
  useEffect(()=>{let active=true;setMessages([]);setTyping([]);setNewMessages(0);setLoading(true);setLoadError('');const load=()=>api<{messages:Message[]}>('/api/channels/'+channel.id+'/messages').then(r=>{if(active){setMessages(r.messages);setLoading(false);requestAnimationFrame(()=>{messagesRef.current?.scrollTo({top:messagesRef.current.scrollHeight});});}}).catch(()=>{if(active){setLoading(false);setLoadError('Não foi possível carregar as mensagens.');}});const join=()=>socket.emit('channel:join',channel.id);load();join();const onMessage=(m:Message)=>{if(m.channel_id!==channel.id)return;setMessages(prev=>prev.some(x=>x.id===m.id)?prev:[...prev,m]);if(!nearBottomRef.current)setNewMessages(value=>value+1);};const onTyping=(d:any)=>{if(d.userId===user.id)return;setTyping(prev=>d.active?Array.from(new Set([...prev,d.displayName])):prev.filter(n=>n!==d.displayName));};const onProfile=(d:any)=>{const changed=d.user as User;setMessages(prev=>prev.map(message=>message.author_id===changed.id?{...message,display_name:changed.display_name,username:changed.username,avatar_icon:changed.avatar_icon,avatar_color:changed.avatar_color,avatar_image:changed.avatar_image}:message));};socket.on('connect',join);socket.on('message:new',onMessage);socket.on('typing',onTyping);socket.on('profile:updated',onProfile);return()=>{active=false;socket.off('connect',join);socket.off('message:new',onMessage);socket.off('typing',onTyping);socket.off('profile:updated',onProfile);};},[channel.id,socket,user.id]);
  function scrollToBottom(smooth=true){messagesRef.current?.scrollTo({top:messagesRef.current.scrollHeight,behavior:smooth?'smooth':'auto'});setNewMessages(0);nearBottomRef.current=true;}
  function handleScroll(){const el=messagesRef.current;if(!el)return;nearBottomRef.current=el.scrollHeight-el.scrollTop-el.clientHeight<96;if(nearBottomRef.current)setNewMessages(0);}
  function update(value:string){setContent(value);setSendError('');socket.emit('typing',{channelId:channel.id,active:true});window.clearTimeout(typingTimer.current);typingTimer.current=window.setTimeout(()=>socket.emit('typing',{channelId:channel.id,active:false}),1200);}
  function send(e:React.FormEvent){e.preventDefault();const text=content.trim();if(!text||pending)return;setPending(true);setSendError('');socket.emit('message:send',{channelId:channel.id,content:text},(r:any)=>{setPending(false);if(!r?.ok){setSendError(r?.error||'Não foi possível enviar. Tente novamente.');return;}setContent('');setSendError('');socket.emit('typing',{channelId:channel.id,active:false});scrollToBottom();});}
  let previousDay='';
  return <div className="chat-area"><div className="messages" ref={messagesRef} onScroll={handleScroll}>{loading&&<div className="loading-state" role="status">Carregando mensagens…</div>}{loadError&&<div className="error-box chat-error" role="alert">{loadError}<button type="button" className="secondary compact-action" onClick={()=>window.location.reload()}>Tentar novamente</button></div>}{!loading&&!loadError&&messages.length===0&&<div className="channel-intro"><span><Hash size={30}/></span><h2>Bem-vindo a #{channel.name}</h2><p>Este é o começo deste canal. Envie a primeira mensagem.</p></div>}{messages.map(m=>{const day=dateLabel(m.created_at);const showDay=day!==previousDay;previousDay=day;return <React.Fragment key={m.id}>{showDay&&<div className="day-divider"><span>{day}</span></div>}<article className="message"><AvatarBadge icon={m.avatar_icon} color={m.avatar_color} image={m.avatar_image} name={m.display_name} small/><div><header><strong>{m.display_name}</strong><time>{time(m.created_at)}</time></header><p>{m.content}</p></div></article></React.Fragment>;})}<div ref={endRef}/>{newMessages>0&&<button className="new-messages" type="button" onClick={()=>scrollToBottom()}>{newMessages} nova{newMessages>1?'s':''} mensagem{newMessages>1?'s':''}</button>}</div><div className="typing-line" aria-live="polite">{typing.length?`${typing.join(', ')} está digitando…`:'\u00a0'}</div>{sendError&&<div className="chat-send-error" role="alert">{sendError}</div>}<form className="composer" onSubmit={send}><textarea aria-label={`Mensagem em #${channel.name}`} rows={1} maxLength={4000} value={content} onChange={e=>update(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send(e);}}} placeholder={`Mensagem em #${channel.name}`}/><button className="send" disabled={!content.trim()||pending} aria-label="Enviar mensagem">{pending?'…':<Send size={18}/>}</button></form></div>;
}

function ProfileSettings({user,onClose,onUpdated}:{user:User;onClose:()=>void;onUpdated:(user:User)=>void}){
  const [icon,setIcon]=useState(user.avatar_icon||'user'); const [color,setColor]=useState(user.avatar_color||'#766cff'); const [file,setFile]=useState<File|null>(null); const [removeImage,setRemoveImage]=useState(false); const [busy,setBusy]=useState(false); const [error,setError]=useState('');
  useEscape(onClose);
  const preview=useMemo(()=>file?URL.createObjectURL(file):removeImage?null:user.avatar_image,[file,removeImage,user.avatar_image]);
  useEffect(()=>()=>{if(file&&preview)URL.revokeObjectURL(preview);},[file,preview]);
  function chooseFile(event:React.ChangeEvent<HTMLInputElement>){const selected=event.target.files?.[0];if(!selected)return;const problem=validateImageFile(selected);if(problem){setError(problem);event.target.value='';return;}setFile(selected);setRemoveImage(false);setError('');}
  async function save(){setBusy(true);setError('');try{let result=await api<{user:User}>('/api/users/me',{method:'PATCH',body:JSON.stringify({avatarIcon:icon,avatarColor:color})});if(file)result=await uploadImage<{user:User}>('/api/users/me/avatar',file);else if(removeImage&&user.avatar_image)result=await api<{user:User}>('/api/users/me/avatar',{method:'DELETE'});onUpdated(result.user);onClose();}catch(e:any){setError(e.message);}finally{setBusy(false);}}
  return <div className="modal-backdrop profile-backdrop" role="dialog" aria-modal="true" aria-label="Configurar ícone de perfil"><section className="profile-modal"><header><div><span className="eyebrow">SEU PERFIL</span><h2>Personalize seu ícone</h2><p>Envie uma imagem ou combine uma opção predefinida com sua cor preferida.</p></div><button className="icon-button" onClick={onClose} title="Fechar"><X/></button></header><div className="appearance-preview"><AvatarBadge icon={icon} color={color} image={preview} name={user.display_name}/><div><strong>{user.display_name}</strong><span>@{user.username}</span></div></div><div className="upload-controls"><label className="image-upload"><ImagePlus/><span><strong>Enviar imagem</strong><small>PNG, JPG ou WebP · até 2 MB</small></span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={chooseFile}/></label>{preview&&<button className="secondary remove-image" type="button" onClick={()=>{setFile(null);setRemoveImage(true);}}><ImageOff size={17}/>Usar ícone predefinido</button>}</div><AppearancePicker icon={icon} color={color} onIcon={setIcon} onColor={setColor}/>{error&&<div className="error-box">{error}</div>}<footer><button className="secondary" onClick={onClose}>Cancelar</button><button className="primary" disabled={busy} onClick={save}><Save size={17}/>{busy?'Salvando…':'Salvar perfil'}</button></footer></section></div>;
}

type OpsMetrics = {ok:boolean;runtime:{capturedAt:string;uptimeSeconds:number;cpuPercent:number;cpuCores:number;load1:number;memoryUsedMb:number;memoryTotalMb:number;memoryPercent:number;processRssMb:number;network:{downMbps:number;upMbps:number}};realtime:{socketClients:number;onlineUsers:number;activeScreenStreams:number;activeScreenAudioStreams:number;activeCameraStreams:number;maxActiveScreenStreams:number;maxActiveCameraStreams:number};capacity:{status:'ok'|'watch'|'critical';reasons:string[];recommendedViewerVideoLimit:number;recommendedViewerCameraLimit:number;recommendedFocusedQuality:string};scope:{communityIds:string[];channelCount:number}};
function OperationsPanel({communityId}:{communityId:string}){
  const [metrics,setMetrics]=useState<OpsMetrics|null>(null); const [busy,setBusy]=useState(true); const [error,setError]=useState('');
  async function refresh(){setBusy(true);try{setMetrics(await api<OpsMetrics>(`/api/ops/metrics?communityId=${encodeURIComponent(communityId)}`));setError('');}catch(e:any){setError(e.message||'Não foi possível carregar as métricas.');}finally{setBusy(false);}}
  useEffect(()=>{refresh();const timer=window.setInterval(refresh,15000);return()=>window.clearInterval(timer);},[communityId]);
  const statusLabel=metrics?.capacity.status==='critical'?'Atenção imediata':metrics?.capacity.status==='watch'?'Monitorar':'Saudável';
  return <div className="operations-content"><article className="settings-card operations-hero"><header><div><span className="eyebrow">OBSERVABILIDADE</span><h3>Saúde operacional</h3><p>Métricas do servidor, conexões e mídia ativa. Atualização automática a cada 15 segundos.</p></div><div className={'ops-status '+(metrics?.capacity.status||'loading')}><span className="status-dot online"/>{busy&&!metrics?'Carregando…':statusLabel}</div></header>{error&&<div className="error-box">{error}</div>}{metrics&&<><div className="ops-metric-grid"><div className="ops-metric"><span>CPU do app</span><strong>{metrics.runtime.cpuPercent.toFixed(1)}%</strong><small>{metrics.runtime.cpuCores} vCPU · carga {metrics.runtime.load1.toFixed(2)}</small></div><div className="ops-metric"><span>Memória do host</span><strong>{metrics.runtime.memoryPercent.toFixed(1)}%</strong><small>{metrics.runtime.memoryUsedMb} / {metrics.runtime.memoryTotalMb} MB</small></div><div className="ops-metric"><span>Tráfego</span><strong>↑ {metrics.runtime.network.upMbps.toFixed(2)} Mbps</strong><small>↓ {metrics.runtime.network.downMbps.toFixed(2)} Mbps</small></div><div className="ops-metric"><span>Tempo real</span><strong>{metrics.realtime.onlineUsers} online</strong><small>{metrics.realtime.socketClients} sockets · {metrics.scope.channelCount} canais</small></div></div><div className="ops-detail-grid"><div><span>Streams de tela ativas</span><strong>{metrics.realtime.activeScreenStreams}</strong></div><div><span>Câmeras publicadas</span><strong>{metrics.realtime.activeCameraStreams}</strong></div><div><span>Streams com áudio</span><strong>{metrics.realtime.activeScreenAudioStreams}</strong></div><div><span>RSS do app</span><strong>{metrics.runtime.processRssMb} MB</strong></div><div><span>Uptime</span><strong>{Math.floor(metrics.runtime.uptimeSeconds/3600)}h {Math.floor(metrics.runtime.uptimeSeconds/60)%60}m</strong></div></div>{metrics.capacity.reasons.length>0&&<div className="ops-alert"><strong>Recomendação de capacidade</strong><span>{metrics.capacity.reasons.join(' · ')}</span></div>}<div className="ops-guidance"><Gauge size={18}/><span>Para mais de 10 mídias, mantenha o limite local em até <strong>{metrics.capacity.recommendedViewerVideoLimit} telas</strong> e <strong>{metrics.capacity.recommendedViewerCameraLimit} câmeras</strong>; priorize <strong>{metrics.capacity.recommendedFocusedQuality}</strong> para a mídia focada. O painel monitora a tendência; não grava ou envia dados para terceiros.</span></div><footer className="ops-footer"><small>Última leitura: {new Date(metrics.runtime.capturedAt).toLocaleTimeString('pt-BR')}</small><button className="secondary" type="button" onClick={refresh} disabled={busy}><RotateCw size={15}/>Atualizar agora</button></footer></>}</article></div>;
}

function SettingsPanel({community,members,user,onClose,onChanged,onDeleted}:{community:Community;members:Member[];user:User;onClose:()=>void;onChanged:()=>Promise<void>;onDeleted:()=>Promise<void>}){
  const [tab,setTab]=useState<'overview'|'channels'|'members'|'operations'>('overview');
  useEscape(onClose);
  const [name,setName]=useState(community.name); const [icon,setIcon]=useState(community.icon||'users'); const [color,setColor]=useState(community.icon_color||'#766cff'); const [imageFile,setImageFile]=useState<File|null>(null); const [removeImage,setRemoveImage]=useState(false); const [channelName,setChannelName]=useState(''); const [channelType,setChannelType]=useState<'text'|'screen'>('text'); const [confirmation,setConfirmation]=useState(''); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const [notice,setNotice]=useState('');
  const isOwner=community.role==='owner';
  const imagePreview=useMemo(()=>imageFile?URL.createObjectURL(imageFile):removeImage?null:community.icon_image,[imageFile,removeImage,community.icon_image]);
  useEffect(()=>()=>{if(imageFile&&imagePreview)URL.revokeObjectURL(imagePreview);},[imageFile,imagePreview]);
  useEffect(()=>{setName(community.name);setIcon(community.icon||'users');setColor(community.icon_color||'#766cff');setImageFile(null);setRemoveImage(false);setConfirmation('');setError('');setNotice('');},[community.id,community.name,community.icon,community.icon_color,community.icon_image]);
  function chooseCommunityImage(event:React.ChangeEvent<HTMLInputElement>){const selected=event.target.files?.[0];if(!selected)return;const problem=validateImageFile(selected);if(problem){setError(problem);event.target.value='';return;}setImageFile(selected);setRemoveImage(false);setError('');}
  async function run(task:()=>Promise<void>,message:string){setBusy(true);setError('');setNotice('');try{await task();setNotice(message);await onChanged();}catch(e:any){setError(e.message);}finally{setBusy(false);}}
  async function saveIdentity(e:React.FormEvent){e.preventDefault();await run(async()=>{await api(`/api/communities/${community.id}`,{method:'PATCH',body:JSON.stringify({name,icon,iconColor:color})});if(imageFile)await uploadImage(`/api/communities/${community.id}/icon-image`,imageFile);else if(removeImage&&community.icon_image)await api(`/api/communities/${community.id}/icon-image`,{method:'DELETE'});setImageFile(null);setRemoveImage(false);},'Identidade da comunidade atualizada.');}
  async function rotateInvite(){if(!confirm('O convite atual deixará de funcionar. Gerar um novo código?'))return;await run(async()=>{await api(`/api/communities/${community.id}/invite/rotate`,{method:'POST'});},'Novo convite gerado.');}
  async function createChannel(e:React.FormEvent){e.preventDefault();await run(async()=>{await api(`/api/communities/${community.id}/channels`,{method:'POST',body:JSON.stringify({name:channelName,type:channelType})});setChannelName('');},'Canal criado.');}
  async function renameChannel(channel:Channel){const next=prompt('Novo nome do canal:',channel.name)?.trim();if(!next||next===channel.name)return;await run(async()=>{await api(`/api/channels/${channel.id}`,{method:'PATCH',body:JSON.stringify({name:next})});},'Canal renomeado.');}
  async function deleteChannel(channel:Channel){if(!confirm(`Excluir #${channel.name}? As mensagens deste canal serão apagadas.`))return;await run(async()=>{await api(`/api/channels/${channel.id}`,{method:'DELETE'});},'Canal excluído.');}
  async function moveChannel(index:number,direction:-1|1){const next=[...community.channels];const target=index+direction;if(target<0||target>=next.length)return;[next[index],next[target]]=[next[target],next[index]];await run(async()=>{await api(`/api/communities/${community.id}/channels/order`,{method:'PATCH',body:JSON.stringify({channelIds:next.map(channel=>channel.id)})});},'Ordem atualizada.');}
  async function changeRole(member:Member,role:'admin'|'member'){await run(async()=>{await api(`/api/communities/${community.id}/members/${member.id}`,{method:'PATCH',body:JSON.stringify({role})});},'Função atualizada.');}
  async function removeMember(member:Member){if(!confirm(`Remover ${member.display_name} da comunidade?`))return;await run(async()=>{await api(`/api/communities/${community.id}/members/${member.id}`,{method:'DELETE'});},'Membro removido.');}
  async function deleteCommunity(){if(confirmation!==community.name)return;setBusy(true);setError('');try{await api(`/api/communities/${community.id}`,{method:'DELETE',body:JSON.stringify({confirmation})});await onDeleted();}catch(e:any){setError(e.message);setBusy(false);}}
  return <section className="settings-shell">
    <aside className="settings-nav"><div className="settings-community-title"><AvatarBadge icon={community.icon} color={community.icon_color} image={community.icon_image} name={community.name} small server/><div><span className="eyebrow">CONFIGURAÇÕES</span><h2>{community.name}</h2></div></div><nav><button className={tab==='overview'?'active':''} onClick={()=>setTab('overview')}><Settings size={17}/>Visão geral</button><button className={tab==='channels'?'active':''} onClick={()=>setTab('channels')}><Hash size={17}/>Canais</button><button className={tab==='members'?'active':''} onClick={()=>setTab('members')}><UserCog size={17}/>Membros</button><button className={tab==='operations'?'active':''} onClick={()=>setTab('operations')}><Gauge size={17}/>Saúde operacional</button></nav></aside>
    <div className="settings-page"><div className="settings-top"><div><span className="eyebrow">PAINEL ADMINISTRATIVO</span><h1>{tab==='overview'?'Visão geral':tab==='channels'?'Canais':tab==='members'?'Membros':'Saúde operacional'}</h1></div><button className="icon-button close-settings" onClick={onClose} title="Fechar configurações"><X/></button></div>
      {(error||notice)&&<div className={error?'error-box':'success-box'}>{error||notice}</div>}
      {tab==='overview'&&<div className="settings-content"><article className="settings-card identity-card"><header><div><h3>Identidade da comunidade</h3><p>Envie uma imagem ou escolha um ícone e uma cor para todos os membros.</p></div><AvatarBadge icon={icon} color={color} image={imagePreview} name={name||community.name} server/></header><div className="upload-controls"><label className="image-upload"><ImagePlus/><span><strong>Enviar imagem do servidor</strong><small>PNG, JPG ou WebP · até 2 MB</small></span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={chooseCommunityImage}/></label>{imagePreview&&<button className="secondary remove-image" type="button" onClick={()=>{setImageFile(null);setRemoveImage(true);}}><ImageOff size={17}/>Usar ícone predefinido</button>}</div><AppearancePicker icon={icon} color={color} onIcon={setIcon} onColor={setColor}/><form className="settings-form" onSubmit={saveIdentity}><label>Nome da comunidade<input required minLength={2} maxLength={50} value={name} onChange={e=>setName(e.target.value)}/></label><button className="primary" disabled={busy||(name.trim()===community.name&&icon===community.icon&&color===community.icon_color&&!imageFile&&!removeImage)}><Save size={17}/>Salvar identidade</button></form></article><article className="settings-card"><header><div><h3>Convite</h3><p>Compartilhe o código com as pessoas que podem entrar.</p></div></header><div className="invite-control"><code>{community.invite_code}</code><button className="secondary" onClick={()=>navigator.clipboard.writeText(community.invite_code)}><Copy size={16}/>Copiar</button><button className="secondary" disabled={busy} onClick={rotateInvite}><RotateCw size={16}/>Gerar novo</button></div></article>{isOwner&&<article className="settings-card danger-zone"><header><div><h3>Excluir comunidade</h3><p>Esta ação remove canais, mensagens e associações permanentemente.</p></div></header><label>Digite <strong>{community.name}</strong> para confirmar<input value={confirmation} onChange={e=>setConfirmation(e.target.value)}/></label><button className="danger" disabled={busy||confirmation!==community.name} onClick={deleteCommunity}><Trash2 size={17}/>Excluir comunidade</button></article>}</div>}
      {tab==='channels'&&<div className="settings-content"><article className="settings-card"><header><div><h3>Criar canal</h3><p>Adicione conversas de texto ou salas de tela e áudio.</p></div></header><form className="channel-create-form" onSubmit={createChannel}><input required minLength={2} maxLength={40} placeholder="nome-do-canal" value={channelName} onChange={e=>setChannelName(e.target.value)}/><select value={channelType} onChange={e=>setChannelType(e.target.value as 'text'|'screen')}><option value="text">Texto</option><option value="screen">Tela e áudio</option></select><button className="primary" disabled={busy}><Plus size={17}/>Criar canal</button></form></article><article className="settings-card"><header><div><h3>Ordem e gerenciamento</h3><p>Organize, renomeie ou exclua os canais existentes.</p></div></header><div className="managed-list">{community.channels.map((channel,index)=><div className="managed-row" key={channel.id}><span className="channel-type-icon">{channel.type==='text'?<Hash/>:<MonitorUp/>}</span><div><strong>{channel.name}</strong><small>{channel.type==='text'?'Canal de texto':'Tela e áudio'}</small></div><div className="row-actions"><button className="icon-button" disabled={busy||index===0} onClick={()=>moveChannel(index,-1)} title="Mover para cima"><ChevronUp/></button><button className="icon-button" disabled={busy||index===community.channels.length-1} onClick={()=>moveChannel(index,1)} title="Mover para baixo"><ChevronDown/></button><button className="icon-button" disabled={busy} onClick={()=>renameChannel(channel)} title="Renomear"><Pencil/></button><button className="icon-button danger-icon" disabled={busy||community.channels.length<=1} onClick={()=>deleteChannel(channel)} title="Excluir"><Trash2/></button></div></div>)}</div></article></div>}
      {tab==='members'&&<div className="settings-content"><article className="settings-card"><header><div><h3>Membros da comunidade</h3><p>Gerencie funções e remova acessos quando necessário.</p></div><span className="count-badge">{members.length}</span></header><div className="managed-list member-admin-list">{members.map(member=><div className="managed-row" key={member.id}><AvatarBadge icon={member.avatar_icon} color={member.avatar_color} image={member.avatar_image} name={member.display_name} small online={member.online}/><div><strong>{member.display_name}{member.id===user.id&&<em>Você</em>}</strong><small>@{member.username}</small></div><div className="member-role-actions">{isOwner&&member.role!=='owner'?<select value={member.role} disabled={busy} onChange={e=>changeRole(member,e.target.value as 'admin'|'member')}><option value="member">Membro</option><option value="admin">Administrador</option></select>:<span className={`role-pill ${member.role}`}>{member.role==='owner'?'Proprietário':member.role==='admin'?'Administrador':'Membro'}</span>}{member.role!=='owner'&&member.id!==user.id&&(isOwner||community.role==='admin'&&member.role==='member')&&<button className="icon-button danger-icon" disabled={busy} onClick={()=>removeMember(member)} title="Remover membro"><Trash2/></button>}</div></div>)}</div></article></div>}
      {tab==='operations'&&<OperationsPanel communityId={community.id}/>}\n    </div>
  </section>;
}

function App(){
  const [user,setUser]=useState<User|null>(null); const [loading,setLoading]=useState(true); const [communities,setCommunities]=useState<Community[]>([]); const [activeCommunityId,setActiveCommunityId]=useState(''); const [activeChannelId,setActiveChannelId]=useState(''); const [members,setMembers]=useState<Member[]>([]); const [mobilePanel,setMobilePanel]=useState(false); const [settingsOpen,setSettingsOpen]=useState(false); const [profileOpen,setProfileOpen]=useState(false); const [connectionState,setConnectionState]=useState('Conectando…'); const activeCommunityRef=useRef(''); const authGenerationRef=useRef(0);
  const socket=useMemo(()=>user?io({withCredentials:true,autoConnect:true}):null,[user?.id]);
  async function loadCommunities(preferredCommunity?:string){const generation=authGenerationRef.current;const r=await api<{communities:Community[]}>('/api/communities');if(generation!==authGenerationRef.current)return;setCommunities(r.communities);const nextCommunity=r.communities.find(c=>c.id===(preferredCommunity||activeCommunityId))||r.communities[0];if(nextCommunity){setActiveCommunityId(nextCommunity.id);const nextChannel=nextCommunity.channels.find(c=>c.id===activeChannelId)||nextCommunity.channels[0];setActiveChannelId(nextChannel?.id||'');}else{setActiveCommunityId('');setActiveChannelId('');setMembers([]);}}
  async function loadMembers(communityId:string){const generation=authGenerationRef.current;const r=await api<{members:Member[]}>(`/api/communities/${communityId}/members`);if(generation!==authGenerationRef.current||activeCommunityRef.current!==communityId)return;setMembers(r.members);}
  useEffect(()=>{api<{user:User}>('/api/auth/me').then(r=>setUser(r.user)).catch(()=>setUser(null)).finally(()=>setLoading(false));},[]);
  useEffect(()=>{authGenerationRef.current+=1;if(user)loadCommunities();else{setCommunities([]);setActiveCommunityId('');setActiveChannelId('');setMembers([]);}},[user?.id]);
  useEffect(()=>{activeCommunityRef.current=activeCommunityId;if(!activeCommunityId){setMembers([]);return;}loadMembers(activeCommunityId).catch(()=>{});},[activeCommunityId]);
  useEffect(()=>{if(!socket)return;const presence=(d:any)=>setMembers(prev=>prev.map(m=>m.id===d.userId?{...m,online:d.online}:m));const changed=(d:any)=>{const activeId=activeCommunityRef.current;if(d.communityId===activeId){loadCommunities(activeId).catch(()=>{});loadMembers(activeId).catch(()=>{});}};const profile=(d:any)=>{const changedUser=d.user as Partial<User>&{id:string};setMembers(prev=>prev.map(member=>member.id===changedUser.id?{...member,...changedUser}:member));if(changedUser.id===user?.id)setUser(current=>current?{...current,...changedUser}:current);};const onConnect=()=>setConnectionState('Conectado');const onDisconnect=()=>setConnectionState('Offline');const onError=()=>setConnectionState('Reconectando…');setConnectionState(socket.connected?'Conectado':'Conectando…');socket.on('connect',onConnect);socket.on('disconnect',onDisconnect);socket.on('connect_error',onError);socket.on('presence:update',presence);socket.on('community:updated',changed);socket.on('profile:updated',profile);return()=>{socket.off('connect',onConnect);socket.off('disconnect',onDisconnect);socket.off('connect_error',onError);socket.off('presence:update',presence);socket.off('community:updated',changed);socket.off('profile:updated',profile);socket.disconnect();};},[socket,user?.id]);
  const community=communities.find(c=>c.id===activeCommunityId); const channel=community?.channels.find(c=>c.id===activeChannelId);
  async function createCommunity(){const name=prompt('Nome da nova comunidade:')?.trim();if(!name)return;const r=await api<{id:string}>('/api/communities',{method:'POST',body:JSON.stringify({name})});await loadCommunities(r.id);}
  async function joinCommunity(){const code=prompt('Código de convite:')?.trim();if(!code)return;try{const r=await api<{id:string}>('/api/communities/join',{method:'POST',body:JSON.stringify({inviteCode:code})});await loadCommunities(r.id);}catch(e:any){alert(e.message);}}
  async function createChannel(){if(!community)return;const name=prompt('Nome do canal:')?.trim();if(!name)return;const type=confirm('OK para canal de compartilhamento de tela.\nCancelar para canal de texto.')?'screen':'text';try{await api(`/api/communities/${community.id}/channels`,{method:'POST',body:JSON.stringify({name,type})});await loadCommunities(community.id);}catch(e:any){alert(e.message);}}
  async function logout(){authGenerationRef.current+=1;try{await api('/api/auth/logout',{method:'POST'});}finally{socket?.disconnect();setUser(null);setCommunities([]);setActiveCommunityId('');setActiveChannelId('');setMembers([]);setSettingsOpen(false);setProfileOpen(false);}}
  async function refreshSettings(){if(!community)return;await Promise.all([loadCommunities(community.id),loadMembers(community.id)]);}
  async function afterCommunityDeleted(){setSettingsOpen(false);await loadCommunities();}
  if(loading)return <div className="splash"><span className="brand-mark"><MonitorUp/></span><p>Preparando seu espaço…</p></div>;
  if(!user)return <Auth onAuthenticated={setUser}/>;
  return <div className="app-shell">
    <aside className="server-rail"><div className="rail-logo"><MonitorUp size={22}/></div><div className="rail-line"/>{communities.map(c=><button key={c.id} onClick={()=>{setActiveCommunityId(c.id);setActiveChannelId(c.channels[0]?.id||'');setSettingsOpen(false);}} className={'server-bubble '+(c.id===activeCommunityId?'active':'')} title={c.name}><AvatarBadge icon={c.icon} color={c.icon_color} image={c.icon_image} name={c.name} server/></button>)}<button className="server-bubble add" onClick={createCommunity} title="Criar comunidade"><Plus size={20}/></button><button className="server-bubble join" onClick={joinCommunity} title="Entrar por convite">+</button></aside>
    <aside className={'channel-panel '+(mobilePanel?'open':'')}><header><div><span>COMUNIDADE</span><strong>{community?.name||'TelaHub'}</strong></div>{community&&<div className="community-header-actions"><button title="Copiar convite" onClick={()=>navigator.clipboard.writeText(community.invite_code)}><Copy size={16}/></button>{['owner','admin'].includes(community.role)&&<button title="Configurações da comunidade" onClick={()=>{setSettingsOpen(true);setMobilePanel(false);}}><Settings size={17}/></button>}</div>}</header><div className="channel-list"><div className="channel-section"><span>CANAIS DE TEXTO</span>{community&&['owner','admin'].includes(community.role)&&<button onClick={createChannel}><Plus size={15}/></button>}</div>{community?.channels.filter(c=>c.type==='text').map(c=><button key={c.id} className={c.id===activeChannelId?'active':''} onClick={()=>{setActiveChannelId(c.id);setMobilePanel(false);}}><Hash size={18}/><span>{c.name}</span></button>)}<div className="channel-section top-gap"><span>SALAS DE TELA</span></div>{community?.channels.filter(c=>c.type==='screen').map(c=><button key={c.id} className={c.id===activeChannelId?'active':''} onClick={()=>{setActiveChannelId(c.id);setMobilePanel(false);}}><MonitorUp size={18}/><span>{c.name}</span></button>)}</div><footer><button className="profile-trigger" onClick={()=>setProfileOpen(true)} title="Personalizar ícone do perfil"><AvatarBadge icon={user.avatar_icon} color={user.avatar_color} image={user.avatar_image} name={user.display_name}/><span><strong>{user.display_name}</strong><small>@{user.username}</small></span><Pencil size={14}/></button><button onClick={logout} title="Sair"><LogOut size={18}/></button></footer></aside>
    <main>{settingsOpen&&community?<SettingsPanel community={community} members={members} user={user} onClose={()=>setSettingsOpen(false)} onChanged={refreshSettings} onDeleted={afterCommunityDeleted}/>:<><header className="topbar"><button className="mobile-menu" onClick={()=>setMobilePanel(!mobilePanel)} aria-label="Abrir canais" aria-expanded={mobilePanel}>☰</button>{channel?.type==='text'?<Hash size={20}/>:<MonitorUp size={20}/>}<strong>{channel?.name||'selecione-um-canal'}</strong><span>{channel?.type==='text'?'Conversa em tempo real':'Sala de compartilhamento de tela'}</span><div className={'connection '+(connectionState==='Conectado'?'connected':connectionState==='Offline'?'offline':'reconnecting')}><Wifi size={16}/>{connectionState}</div></header>{channel&&socket?(channel.type==='text'?<Chat channel={channel} user={user} socket={socket}/>:<ScreenRoom channel={channel} user={user} socket={socket}/>):<div className="empty-main">Selecione um canal.</div>}</>}</main>
    <aside className="members-panel"><header><Users size={17}/><span>MEMBROS — {members.length}</span></header><div className="members"><p className="member-group">ONLINE</p>{members.filter(m=>m.online||m.id===user.id).map(m=><div className="member" key={m.id}><AvatarBadge icon={m.avatar_icon} color={m.avatar_color} image={m.avatar_image} name={m.display_name} small online/><div><strong>{m.display_name}</strong><span>{m.role==='owner'?'Proprietário':m.role==='admin'?'Administrador':'Membro'}</span></div></div>)}<p className="member-group">OFFLINE</p>{members.filter(m=>!m.online&&m.id!==user.id).map(m=><div className="member offline" key={m.id}><AvatarBadge icon={m.avatar_icon} color={m.avatar_color} image={m.avatar_image} name={m.display_name} small/><div><strong>{m.display_name}</strong><span>Visto recentemente</span></div></div>)}</div></aside>
  {profileOpen&&<ProfileSettings user={user} onClose={()=>setProfileOpen(false)} onUpdated={setUser}/>}</div>;
}

class AppErrorBoundary extends React.Component<{children:React.ReactNode},{error:string}> {
  state={error:''};
  static getDerivedStateFromError(){return{error:'A interface encontrou uma falha inesperada.'};}
  componentDidCatch(error:Error,info:React.ErrorInfo){console.error('TelaHub interface error',error,info);}
  render(){return this.state.error?<div className="fatal-error"><span className="brand-mark"><MonitorUp/></span><h1>Não foi possível abrir este espaço</h1><p>{this.state.error}</p><button className="primary" onClick={()=>location.reload()}>Tentar novamente</button></div>:this.props.children;}
}

createRoot(document.getElementById('root')!).render(<React.StrictMode><AppErrorBoundary><App/></AppErrorBoundary></React.StrictMode>);
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
